func (q *Queries) GetHostMembers(ctx context.Context, hostID pgtype.UUID) ([]HostMember, error) {
	rows, err := q.db.Query(ctx, getHostMembers, hostID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []HostMember{}
	for rows.Next() {
		var i HostMember
		if err := rows.Scan(
			&i.ID,
			&i.HostID,
			&i.UserID,
			&i.Role,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

