const updateTournament = `-- name: UpdateTournament :one
UPDATE tournaments
SET 
    name = COALESCE($2, name),
    description = COALESCE($3, description),
    scheduled_start_time_at = COALESCE($4, scheduled_start_time_at),
    minimum_team_count = COALESCE($5, minimum_team_count),
    maximum_team_count = COALESCE($6, maximum_team_count),
    updated_at = NOW()
WHERE id = $1
RETURNING 
    id, host_id, name, description, external_id,
    status, scheduled_start_time_at, registration_window_open_at,
    actual_start_time_at, completed_at, cancelled_at,
    minimum_team_count, maximum_team_count, team_size, auto_force_ready,
    game_id, space_id, template_id,
    created_at, updated_at
`

